<?php require __DIR__.'/bootstrap.php';$d=body();requireFields($d,['news_id','status']);if(!in_array($d['status'],['related','unrelated','manual_review'],true))fail('Status inválido');$p=db();$p->beginTransaction();$st=$p->prepare('SELECT relevance_status FROM news WHERE id=? FOR UPDATE');$st->execute([(int)$d['news_id']]);$old=$st->fetchColumn();if($old===false)fail('Notícia não encontrada',404);$p->prepare('UPDATE news SET relevance_status=?,manual_reviewed=1,is_new=0 WHERE id=?')->execute([$d['status'],(int)$d['news_id']]);$p->prepare('INSERT INTO manual_reviews(news_id,previous_status,new_status,notes) VALUES(?,?,?,?)')->execute([(int)$d['news_id'],$old,$d['status'],clean($d['notes']??'')]);$p->commit();respond(['updated'=>true]);
